insert into competencias_bncc (codigo, disciplina, ano, unidade_tematica, descricao) values
  ('EF06MA01', 'matematica', '6o ano', 'Números', 'Comparar, ordenar, ler e escrever números naturais e números racionais cuja representação decimal é finita, fazendo uso da reta numérica.'),
  ('EF06MA02', 'matematica', '6o ano', 'Números', 'Reconhecer o sistema de numeração decimal, como o que prevaleceu no mundo ocidental, e destacar semelhanças e diferenças com outros sistemas, de modo a sistematizar suas principais características (base, valor posicional e função do zero), utilizando, inclusive, a composição e decomposição de números naturais e números racionais em sua representação decimal.'),
  ('EF06MA03', 'matematica', '6o ano', 'Números', 'Resolver e elaborar problemas que envolvam cálculos (mentais ou escritos, exatos ou aproximados) com números naturais, por meio de estratégias variadas, com compreensão dos processos neles envolvidos com e sem uso de calculadora.'),
  ('EF06MA04', 'matematica', '6o ano', 'Números', 'Construir algoritmo em linguagem natural e representá-lo por fluxograma que indique a resolução de um problema simples (por exemplo, se um número natural qualquer é par).'),
  ('EF06MA05', 'matematica', '6o ano', 'Números', 'Classificar números naturais em primos e compostos, estabelecer relações entre números, expressas pelos termos “é múltiplo de”, “é divisor de”, “é fator de”, e estabelecer, por meio de investigações, critérios de divisibilidade por 2, 3, 4, 5, 6, 8, 9, 10, 100 e 1000.'),
  ('EF06MA06', 'matematica', '6o ano', 'Números', 'Resolver e elaborar problemas que envolvam as ideias de múltiplo e de divisor.'),
  ('EF06MA07', 'matematica', '6o ano', 'Números', 'Compreender, comparar e ordenar frações associadas às ideias de partes de inteiros e resultado de divisão, identificando frações equivalentes.'),
  ('EF06MA08', 'matematica', '6o ano', 'Números', 'Reconhecer que os números racionais positivos podem ser expressos nas formas fracionária e decimal, estabelecer relações entre essas representações, passando de uma representação para outra, e relacioná-los a pontos na reta numérica.'),
  ('EF06MA09', 'matematica', '6o ano', 'Números', 'Resolver e elaborar problemas que envolvam o cálculo da fração de uma quantidade e cujo resultado seja um número natural, com e sem uso de calculadora.'),
  ('EF06MA10', 'matematica', '6o ano', 'Números', 'Resolver e elaborar problemas que envolvam adição ou subtração com números racionais positivos na representação fracionária.'),
  ('EF06MA11', 'matematica', '6o ano', 'Números', 'Resolver e elaborar problemas com números racionais positivos na representação decimal, envolvendo as quatro operações fundamentais e a potenciação, por meio de estratégias diversas, utilizando estimativas e arredondamentos para verificar a razoabilidade de respostas, com e sem uso de calculadora.'),
  ('EF06MA12', 'matematica', '6o ano', 'Números', 'Fazer estimativas de quantidades e aproximar números para múltiplos da potência de 10 mais próxima.'),
  ('EF06MA13', 'matematica', '6o ano', 'Números', 'Resolver e elaborar problemas que envolvam porcentagens, com base na ideia de proporcionalidade, sem fazer uso da “regra de três”, utilizando estratégias pessoais, cálculo mental e calculadora, em contextos de educação financeira, entre outros.'),
  ('EF06MA14', 'matematica', '6o ano', 'Álgebra', 'Reconhecer que a relação de igualdade matemática não se altera ao adicionar, subtrair, multiplicar ou dividir os seus dois membros por um mesmo número e utilizar essa noção para determinar valores desconhecidos na resolução de problemas.'),
  ('EF06MA15', 'matematica', '6o ano', 'Álgebra', 'Resolver e elaborar problemas que envolvam a partilha de uma quantidade em duas partes desiguais, envolvendo relações aditivas e multiplicativas, bem como a razão entre as partes e entre uma das partes e o todo.'),
  ('EF06MA16', 'matematica', '6o ano', 'Geometria', 'Associar pares ordenados de números a pontos do plano cartesiano do 1º quadrante, em situações como a localização dos vértices de um polígono.'),
  ('EF06MA17', 'matematica', '6o ano', 'Geometria', 'Quantificar e estabelecer relações entre o número de vértices, faces e arestas de prismas e pirâmides, em função do seu polígono da base, para resolver problemas e desenvolver a percepção espacial.'),
  ('EF06MA18', 'matematica', '6o ano', 'Geometria', 'Reconhecer, nomear e comparar polígonos, considerando lados, vértices e ângulos, e classificá-los em regulares e não regulares, tanto em suas representações no plano como em faces de poliedros.'),
  ('EF06MA19', 'matematica', '6o ano', 'Geometria', 'Identificar características dos triângulos e classificá-los em relação às medidas dos lados e dos ângulos.'),
  ('EF06MA20', 'matematica', '6o ano', 'Geometria', 'Identificar características dos quadriláteros, classificá-los em relação a lados e a ângulos e reconhecer a inclusão e a intersecção de classes entre eles.'),
  ('EF06MA21', 'matematica', '6o ano', 'Geometria', 'Construir figuras planas semelhantes em situações de ampliação e de redução, com o uso de malhas quadriculadas, plano cartesiano ou tecnologias digitais.'),
  ('EF06MA22', 'matematica', '6o ano', 'Geometria', 'Utilizar instrumentos, como réguas e esquadros, ou softwares para representações de retas paralelas e perpendiculares e construção de quadriláteros, entre outros.'),
  ('EF06MA23', 'matematica', '6o ano', 'Geometria', 'Construir algoritmo para resolver situações passo a passo (como na construção de dobraduras ou na indicação de deslocamento de um objeto no plano segundo pontos de referência e distâncias fornecidas etc.).'),
  ('EF06MA24', 'matematica', '6o ano', 'Grandezas e Medidas', 'Resolver e elaborar problemas que envolvam as grandezas comprimento, massa, tempo, temperatura, área (triângulos e retângulos), capacidade e volume (sólidos formados por blocos retangulares), sem uso de fórmulas, inseridos, sempre que possível, em contextos oriundos de situações reais e/ou relacionadas às outras áreas do conhecimento.'),
  ('EF06MA25', 'matematica', '6o ano', 'Grandezas e Medidas', 'Reconhecer a abertura do ângulo como grandeza associada às figuras geométricas.'),
  ('EF06MA26', 'matematica', '6o ano', 'Grandezas e Medidas', 'Resolver problemas que envolvam a noção de ângulo em diferentes contextos e em situações reais, como ângulo de visão.'),
  ('EF06MA27', 'matematica', '6o ano', 'Grandezas e Medidas', 'Determinar medidas da abertura de ângulos, por meio de transferidor e/ou tecnologias digitais.'),
  ('EF06MA28', 'matematica', '6o ano', 'Grandezas e Medidas', 'Interpretar, descrever e desenhar plantas baixas simples de residências e vistas aéreas.'),
  ('EF06MA29', 'matematica', '6o ano', 'Grandezas e Medidas', 'Analisar e descrever mudanças que ocorrem no perímetro e na área de um quadrado ao se ampliarem ou reduzirem, igualmente, as medidas de seus lados, para compreender que o perímetro é proporcional à medida do lado, o que não ocorre com a área.'),
  ('EF06MA30', 'matematica', '6o ano', 'Probabilidade e Estatística', 'Calcular a probabilidade de um evento aleatório, expressando-a por número racional (forma fracionária, decimal e percentual) e comparar esse número com a probabilidade obtida por meio de experimentos sucessivos.'),
  ('EF06MA31', 'matematica', '6o ano', 'Probabilidade e Estatística', 'Identificar as variáveis e suas frequências e os elementos constitutivos (título, eixos, legendas, fontes e datas) em diferentes tipos de gráfico.'),
  ('EF06MA32', 'matematica', '6o ano', 'Probabilidade e Estatística', 'Interpretar e resolver situações que envolvam dados de pesquisas sobre contextos ambientais, sustentabilidade, trânsito, consumo responsável, entre outros, apresentadas pela mídia em tabelas e em diferentes tipos de gráficos e redigir textos escritos com o objetivo de sintetizar conclusões.'),
  ('EF06MA33', 'matematica', '6o ano', 'Probabilidade e Estatística', 'Planejar e coletar dados de pesquisa referente a práticas sociais escolhidas pelos alunos e fazer uso de planilhas eletrônicas para registro, representação e interpretação das informações, em tabelas, vários tipos de gráficos e texto.'),
  ('EF06MA34', 'matematica', '6o ano', 'Probabilidade e Estatística', 'Interpretar e desenvolver fluxogramas simples, identificando as relações entre os objetos representados (por exemplo, posição de cidades considerando as estradas que as unem, hierarquia dos funcionários de uma empresa etc.).')
